package es.codeurjc.daw.library.repository;



import es.codeurjc.daw.library.model.User; // to be able to work with user entity
import org.springframework.data.jpa.repository.JpaRepository; // to inherit crud operations





public interface UserRepository extends JpaRepository<User, Long> {
    /**
     * custom query method to find  user by (unique) email
     * sql auto generated by jpa
     * @param email users email address
     * @return user object if found, null otherwise
     */
    User findByEmail (String email);
}